@preconcurrency import AVFAudio
import Foundation
import Speech
import VCModels

/// Locates `.fixtures/` (generated by `swift scripts/MakeFixtures.swift`) and the speech assets tests need.
enum Fixtures {
    static let directory: URL? = {
        if let env = ProcessInfo.processInfo.environment["VOICCENGER_FIXTURES"] {
            return URL(fileURLWithPath: env, isDirectory: true)
        }
        var dir = URL(fileURLWithPath: #filePath).resolvingSymlinksInPath().deletingLastPathComponent()
        while dir.path != "/" {
            let candidate = dir.appendingPathComponent(".fixtures", isDirectory: true)
            if FileManager.default.fileExists(atPath: candidate.appendingPathComponent("meeting.wav").path) {
                return candidate
            }
            dir.deleteLastPathComponent()
        }
        return nil
    }()

    static func url(_ name: String) -> URL? {
        guard let url = directory?.appendingPathComponent(name),
            FileManager.default.fileExists(atPath: url.path)
        else { return nil }
        return url
    }

    /// True when the files exist, SpeechTranscriber runs here and every locale's assets are installed.
    static func ready(files: [String], locales: [String]) async -> Bool {
        guard files.allSatisfy({ url($0) != nil }), SpeechTranscriber.isAvailable else { return false }
        let installed = Set(await SpeechTranscriber.installedLocales.map { $0.identifier(.bcp47) })
        return locales.allSatisfy(installed.contains)
    }

    /// Mono Float32 samples (first channel) and sample rate.
    static func samples(_ name: String) throws -> (samples: [Float], sampleRate: Double) {
        guard let url = url(name) else { throw CocoaError(.fileNoSuchFile) }
        let file = try AVAudioFile(forReading: url)
        guard
            let buffer = AVAudioPCMBuffer(
                pcmFormat: file.processingFormat, frameCapacity: AVAudioFrameCount(file.length)),
            file.processingFormat.commonFormat == .pcmFormatFloat32
        else { throw CocoaError(.fileReadCorruptFile) }
        try file.read(into: buffer)
        let channel = buffer.floatChannelData![0]
        return (Array(UnsafeBufferPointer(start: channel, count: Int(buffer.frameLength))), file.processingFormat.sampleRate)
    }

    struct Turn: Decodable {
        let start: Double
        let end: Double
        let text: String
        let speaker: String
    }

    static func meetingTruth() throws -> [Turn] {
        guard let url = url("meeting.truth.json") else { throw CocoaError(.fileNoSuchFile) }
        return try JSONDecoder().decode([Turn].self, from: Data(contentsOf: url))
    }
}

/// Collects transcriber events concurrently so the producer never waits on the test.
actor EventLog {
    private(set) var events: [TranscriptEvent] = []

    func append(_ event: TranscriptEvent) { events.append(event) }

    var finals: [TranscriptUpdate] {
        events.compactMap { if case .final(let u) = $0 { u } else { nil } }
    }

    var localeChanges: [(from: String, to: String)] {
        events.compactMap { if case .localeChanged(_, let from, let to, _) = $0 { (from, to) } else { nil } }
    }

    var volatileCount: Int {
        events.reduce(0) { if case .volatile = $1 { $0 + 1 } else { $0 } }
    }

    static func collecting(_ stream: AsyncStream<TranscriptEvent>) -> (EventLog, Task<Void, Never>) {
        let log = EventLog()
        let task = Task {
            for await event in stream { await log.append(event) }
        }
        return (log, task)
    }
}
